const LOTES=[{"codigo":"aleam-enfermeiro-2025","ano":2025,"orgao":"Assembleia Legislativa do Estado do Amazonas","cargo":"Analista Legislativo — Enfermeiro","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/analista-legislativo-enfermeiro-cns313-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/gabarito-definitivo-ale-am.pdf","itens":[{"n":1,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"Uma marca estrutural de um texto é a presença do paralelismo sintático, ou seja, da repetição de uma mesma construção. Assinale a opção que documenta essa estrutura.","alternativas":["Há flores em todas as estações, assim como loucuras em todas as idades.(Jouy)","Eu sou homem na natureza antes de ser da sociedade. (Marquês de Sade)","Considerai como crescem os lírios do campo; eles não trabalham nem fiam. (Mateus 6, 28)","Pois a arte pode errar, mas a natureza não falha. (John Dryden)","Não está provado que a pulga, que vive no camundongo, tema o gato. (Henri Michaux)"],"correta":"A"},{"n":2,"disciplina":"Língua Portuguesa","tema":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Um tipo de figura de retórica muito conhecido é a prosopopeia, na qual se atribuem qualidades e características humanas a seres irracionais ou inanimados. Das seguintes frases retiradas de obras de Machado de Assis, identifique a que exemplifica uma prosopopeia.","alternativas":["“Tudo neve; chegava a gelar -nos um sol de neve.” ( Memórias Póstumas de Brás Cubas)","“Foi uma cena de delírio; o cachorro pagava as carícias de Rubião, latindo, p ulando, beijando -lhe as mãos”. ( Quincas Borba)","“Ninguém o viu em todo esse tempo nos lugares onde ele era mais assíduo. Foram seis dias, não digo de reclusão, mas de completa solidão.” (A Mão e a Luva)","“Não estava magra; estava transparente.” ( Memórias Póstumas de Brás Cubas)","“Eu não sou propriamente um autor defunto, mas um defunto autor.” (Memórias Póstumas de Brás Cubas)"],"correta":"B"},{"n":3,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Leia com atenção o texto a seguir, retirado do romance lusitano O Barão de Lavos. “Naquela noite de març o, desabrida e húmida, uma grande animação fervilhava alacremente ao fundo da Rua do Salitre. Era em 1867. Frente a frente, as Variedades e o Circo Price alinhavam os seus bicos de gás festeiros, a que as vergastadas do noroeste impunham um tremelilhar inq uieto. Quinta feira — noite de cabriolas com sobrescrito à fina sociedade. Enchente certa no Circo. De cada lado do portal da entrada, um semicírculo compacto de gente se agitava, tendo por centro cada um seu postigo de bilheteiro, e ambos por igual colado s, premidos sofregamente contra a parede verdoenga do barracão, e arredondando pela rua fora, numa irregularidade gritada e confusa, a toda a largura do macadame.” Sobre a sua tipologia textual, assinale a afirmativa correta.","alternativas":["Trata-se de um texto narra tivo, que mostra as ações de uma noite de enchente num circo.","Mostra um texto de tipo informativo sobre uma sequência de acontecimentos ocorridos numa noite de março.","Exemplifica um texto publicitário, divulgando as atividades de uma empresa circense.","Apresenta um texto descritivo, tendo por foco o cenário de uma noite agitada em função da presença de um circo.","Compõe-se de frases que, indiretamente, recomendam ao leitor a ida ao circo, exemplificando um texto injuntivo"],"correta":"D"},{"n":4,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Observe o texto a seguir. “Hoje é fácil iludirmo -nos, crendo ver nas revoluções e lutas do ocidente da Península no decurso dos séculos VIII a XII a anarquia feudal, confundindo esta com a anarquia aristocrática. Não era a hierarquia constituindo uma espécie de famílias militares, de clãs ou tribos artificiais, cujos membros estavam ligados por mútuos direitos e deveres, determinados por um certo modo de fruição de domínio territorial, em que se achava incorporada a soberania com exclusão do poder público. Em vez disto, era o individualismo rebelando-se contra esse poder, contra a unidade, contra o direito. Quando as mãos que retinham o cetro eram frouxas ou inabilmente violentas, as perturbações tornavam -se não só possíveis, mas, até, fáceis. A febre d a anarquia podia ser ardente: o que não havia era a anarquia crônica, a anarquia organizada.” (Alexandre Herculano, O Bobo) Assinale a opção que mostra uma informação correta sobre aspectos da coesão nele realizada.","alternativas":["O pronome demonstrativo “esta” se re fere a “anarquia aristocrática”, em exemplo de catáfora.","O pronome relativo “cujos” tem como referente de coesão o substantivo “membros”.","O adjetivo “determinados” tem como referente os substantivos “direitos e deveres”.","O demonstrativo “disto” se refere ao termo “individualismo”, citado a seguir.","O demonstrativo “esse” se refere a “soberania”"],"correta":"C"},{"n":5,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"Todas as opções a seguir enumeram, respectivamente, um tema textual e uma frase pertinente a ele; todas da autoria de Machado de Assis. Assinale a opção em que a relação tema/frase está inadequada.","alternativas":["Religião – Jesus disse: não se colhem figos dos abrolhos”.(Helena)","Aparências – “As coisas boas são belas por si mesmas; por isso é comum vermos um rosto feio abrigando um elevado espírito.” (Contos)","Amizade – “Quem não tem dinheiro não tem amigos.” (Crônicas)","Ambientalismo – “Cumpre vencer o caminho a todo o custo; no fim há sempre uma tenda para descansar, e uma relva para dormir”. (Crônicas)","Catolicismo – “Quem esperará que a Igreja reconheça nenhum outro matrimônio, além do católico? (A Semana)"],"correta":"D"},{"n":6,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Observe o texto abaixo, retirado do livro “Composições Infantis”, da autoria de Millôr Fernandes. “O leão é um animal que há muito tempo não vai ao barbeiro. Senão teria cortado o cabelo e ficaria muito igual à mulher dele. O leão tem a cabeça muito grande que é para não poder fugir da jaula. Agora na jaula quem põe ele lá é o guarda e aí está por que é o rei dos animais. O leão dizem que é feroz, mas deve ser quando a gente não está olhando porque quando a gente está olhando ele fica o tempo todo dormindo e não há jeito de enferocizá-lo e quem fica furioso com isso é o guarda. O leão também papai gosta muito de jogar nele, mas isso só quando sonha com elefante. E aí é que dá cobra.” A observação correta sobre esse segmento textual","alternativas":["a linguagem empregada no texto mostra um desprezo geral pela gramática da língua, causando incompreensão.","a descriçã o do leão é prejudicada pela limitação de conhecimento do observador.","a descrição feita do leão concentra seu interesse no aspecto físico do animal.","o final do texto marca traços de infantilidade em função da falta de coerência.","o texto traz, i ndiretamente, um protesto contra o jogo do bicho, por sua ilegalidade"],"correta":"B"},{"n":7,"disciplina":"Língua Portuguesa","tema":"Coordenação e Subordinação","enunciado":"Assinale a opção que apresenta uma oração reduzida de infinitivo, com valor concessivo","alternativas":["Nos outros times, sem sairmos do futebol brasileiro, os técnicos são mais disc retos.","Por desconhecerem os endereços, não enviam correspondência.","Agradava-me conversar com o cronista no almoço.","Vou sair já daqui para fazer as compras.","O deputado queria a chefia sem ser especialista em Economia"],"correta":"E"},{"n":8,"disciplina":"Língua Portuguesa","tema":"Concordância Verbal e Nominal","enunciado":"No trecho “daí os pedidos com que nos vemos assaltados os médicos” há uma particularidade de concordância, que é","alternativas":["a silepse de número.","a silepse de pessoa.","a silepse de número e pessoa.","a concordância por atração.","a silepse de gênero"],"correta":"B"},{"n":10,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"Tendo em vista que as palavras a seguir aparecem, propositalmente, sem acento gráfico, assinale o conjunto desses vocábulos que apresenta a mesma classificação quanto à sílaba tônica.","alternativas":["interim / decada / rubrica / alcoolatra","gratuito / decano / prototipo / crisantemo","exodo / alcool / epiteto / maquinaria","novel / sutil / ruim / refem","alibi / aziago / avaro / climax"],"correta":"D"},{"n":11,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"Numa redação de concurso público, um candidato escreveu o seguinte fragmento textual: “De fato, a televisão é um passatempo prejudicial, pois, além de propiciar distração às pessoas, reduz-lhes o tempo que poderia ser dedicado à família.” Nesse caso, o erro detectado é","alternativas":["a ausência de paralelismo sintático.","a ambiguidade de termos.","a incoerência no emprego do conectivo.","o erro de regência verbal.","a falta de concisão."],"correta":"A"},{"n":12,"disciplina":"Língua Portuguesa","tema":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"Entre as seguintes frases, retiradas de obras de Machado de Assis, assinale aquela que não representa um exemplo de pleonasmo semântico.","alternativas":["“Marcela juntava as joias todas dentro de uma caixinha de ferro, cuja chave ninguém nunca jamais soube onde ficava;” (Memórias Póstumas de Brás Cubas)","“Os homens, esses ou não sentem ou abafam o que sentem.” (Ressurreição)","“Então resolvia embarcar imediatamente para cortar a minha vida em duas metades.” (Memórias Póstumas de Brás Cubas)","“Casos de estudo, incidentes de nada, um livro, um mote, toda a velha papelada saiu cá fora, e rimos juntos.” (Dom Casmurro)","“Se alguma vez o reconheceste, não foi ontem; ontem cedeste a um mau preconceito contra as madrastas. (Iaiá Garcia)"],"correta":"B"},{"n":13,"disciplina":"Língua Portuguesa","tema":"Classes de Palavras","enunciado":"Entre as frases abaixo, retiradas do livro O Mulato , de Aluísio Azevedo, aquela que mostra a expressão “é que” com valor sintático, ou seja, não tendo valor de ênfase, é a seguinte:","alternativas":["“— Ah!... volveu terrível o Freitas, é que ela hoje é outra coisa!... Hoje não se compara! — há muito mais luxo, mas muito!”","“— O que lhe posso afiançar, doutor, é que não há criança que, nessa tarde, não tenha a sua pratinha amarrada na ponta do lenço.”","“Só depois de cinquenta e seis anos, é que o governador Joaquim de Melo e Póvoas mandou abrir uma boa estrada, a qual vem a ser hoje a nossa pitoresca Rua dos Remédios.”","“— Meu caro senhor Mundico, hoj’em dia já não se acredita em coisa alguma!... por isso é que os tempos estão como estão — cheios de febres, de bexigas, de tísicas e de paralisias, que nem mesmo os doutores de carta sabem o que aquilo é!”","“— Credo, minha Nossa Senhora! que inferno não irá por esse mundão de esconjurados! Por isso é que agora está se vendo o que se vê, benza-me Deus!”"],"correta":"B"},{"n":14,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"“Não, não direi que assisti às alvoradas do romantismo, que também eu fui fazer poesia efeti va no regaço da Itália; não direi coisa nenhuma.” (Memórias Póstumas de Brás Cubas) Nessa frase há um aspecto diferente na estruturação, que é","alternativas":["a falta de coerência, pois o narrador acaba dizendo o que afirma não dizer.","a repetição desnecessária de termos, o que ocorre com a expressão “não direi”.","o descaso com a norma gramatical, com erros de pontuação e concordância.","a ausência de elementos de coesão, tornando as frases desconexas.","A utilização excessiva de palavras, causando redundâncias"],"correta":"A"},{"n":15,"disciplina":"Língua Portuguesa","tema":"Coesão e Coerência","enunciado":"Em todas as frases a seguir ocorre uma estratégia de evitar -se a repetição de termos idênticos. Assinale a frase em que a estratégia utilizada é a nominalização do termo anterior.","alternativas":["Diego Souza foi eleito, em 2018 , o melhor jogador do campeonato brasileiro; no ano seguinte, Diego se aposentou.","Trabalhar é considerado um castigo por muitos, mas o trabalho também tem aspectos positivos.","A Polícia Federal está encarregada de várias investigações, mas certamente outras chegarão à PF.","A família acabou de comprar uma casa em Mato Grosso, mas a nova casa ainda demora a ficar reformada.","Todos os candidatos devem apresentar declarações de renda, mas elas demoram a ficar prontas. Raciocínio Lógico e Matemático"],"correta":"B"},{"n":17,"disciplina":"Raciocínio Lógico e Matemática","tema":"Regra de Três e Problemas Aritméticos","enunciado":"4 galinhas e 5 patos comem 1300 g de ração por dia. 5 galinhas e 4 patos comem 1220 g de ração por dia. A quantidade de ração que 2 galinhas e 1 pato comerão, por dia, equivale a","alternativas":["350 g.","360 g.","370 g.","380 g.","390 g"],"correta":"D"},{"n":18,"disciplina":"Raciocínio Lógico e Matemática","tema":"Probabilidade","enunciado":"Um grupo é formado por seis pessoas, todas com idades diferentes. Dessas pessoas, três serão sorteadas aleatoriamente. A probabilidade, de que as duas pessoas mais jovens estejam entre as sorteadas, é igual a","alternativas":["1/4.","1/5.","1/6.","1/8.","1/9"],"correta":"B"},{"n":19,"disciplina":"Raciocínio Lógico e Matemática","tema":"Equivalências e Negações","enunciado":"A negação de “Nenhum advogado é ingênuo” é:","alternativas":["Há, pelo menos, um advogado ingênuo.","Alguns ingênuos são advogados.","Todos os advogados são ingênuos.","Todos os ingênuos são advogados.","Todos os advogados não são ingênuos"],"correta":"A"},{"n":20,"disciplina":"Raciocínio Lógico e Matemática","tema":"Regra de Três e Problemas Aritméticos","enunciado":"A soma de três números naturais diferentes é 2025. Sabe-se que a diferença entre o maior e o menor desses números é menor que 10. O menor valor possível para o menor dos três números é igual a","alternativas":["666.","667.","668.","669.","670"],"correta":"E"},{"n":21,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"Joana gasta 40% do seu salário em moradia. Do que sobra, ela gasta 40% em alimentação. O restante do seu salário ela usa para “outras despesas”. A porcentagem do salário de Joana que ela usa para “outras despesas” é:","alternativas":["20%.","24%.","30%.","36%.","40%"],"correta":"D"},{"n":23,"disciplina":"Raciocínio Lógico e Matemática","tema":"Razão, Proporção e Porcentagem","enunciado":"Três grandezas positivas X, Y e Z são tais que Y é diretamente proporcional ao quadrado de X e Z é inversamente proporcional a Y. Quando X = 4, tem-se Y = 48 e Z = 2. Quando Z = 8, o valor de X + Y é:","alternativas":["10.","12.","14.","16.","18. Figura 2 Figura 1"],"correta":"C"},{"n":24,"disciplina":"Raciocínio Lógico e Matemática","tema":"Sequências e Padrões","enunciado":"Uma sequência de números racionais é tal que cada termo de ordem k, a partir do terceiro termo, é a razão entre o termo de ordem k – 1 e o termo de ordem k – 2. Por exemplo, o terceiro termo é a razão entre o segundo e o primeiro termos. Sabe-se que o quinto e o sétimo ter mos dessa sequência são respectivamente, 3 e 2/3. O terceiro termo dessa sequência é:","alternativas":["1/2.","1/3.","2/3.","2.","3"],"correta":"A"},{"n":25,"disciplina":"Raciocínio Lógico e Matemática","tema":"Análise Combinatória","enunciado":"Considere as 5 letras da sigla ALEAM. O número de maneiras de escrever essas 5 letras em sequência de modo que as letras L e M não fiquem juntas é:","alternativas":["15.","20.","24.","32.","36. Noções de Informática"],"correta":"E"},{"n":26,"disciplina":"Informática","tema":"Windows","enunciado":"Um técnico precisa classificar e organizar uma grande coleção de mídias em um computador que utiliza o Sistema Operacional Windows 10. Para garantir a correta identificação dos arquivos de áudio, vídeo, imagem e planilhas, ele deve conhecer os principais padrões e suas extensões. Considerando os padrões de arquivos digitais, assinale a extensão que é universalmente reconhecida como um formato de arquivo de vídeo, que combina áudio e vídeo e é amplamente utilizado em streaming e dispositivos móveis.","alternativas":[".ZIP",".MP4",".DOCX",".PDF",".PNG"],"correta":"B"},{"n":27,"disciplina":"Informática","tema":"Microsoft Word","enunciado":"Ao finalizar a redação de um extenso relatório técnico no MS Word 2010 BR ou superior, um analista precisa garantir que o Anexo do documento inicie sempre em uma nova página e tenha uma formatação d e rodapé diferente (por exemplo, numeração em algarismos romanos) em relação ao corpo principal do texto (que usa numeração em algarismos arábicos). Assinale o recurso de formatação de página que o analista deve utilizar para atingir o objetivo de iniciar o Anexo em uma nova página e permitir a alteração independente da formatação dos rodapés/cabeçalhos.","alternativas":["Quebra de linha (Shift + Enter).","Quebra de Página (Ctrl + Enter).","Quebra de Coluna.","Quebra de Seção – Próxima Página.","Quebra de Seção – Contínua"],"correta":"D"},{"n":28,"disciplina":"Informática","tema":"Segurança da Informação","enunciado":"Uma Macro (sequência de comandos gravada) é uma poderosa ferramenta de automação. No entanto, ela pode ser um vetor de segurança e requer proteção contra visualização e edição não autorizada em ambientes controlados. Considerando o MS Word 2010 BR ou superior e a arquitetura VBA comum ao Excel, a medida de segurança mais adequada para evitar que um usuário não autorizado visualize ou altere o código fonte de uma Macro armazenada em um documento é:","alternativas":["Definir uma senha de proteção para o documento na opção \"Proteger Documento\" na guia Revisão.","Habilitar o recurso \"Controlar Alterações\" para que todas as modificações no código da Macro sejam registradas.","Configurar a \"Proteção do Projeto VBA\" com uma senha específica, acessando as propriedades do pro jeto VBA no ambiente de edição.","Assinar digitalmente a Macro, garantindo apenas que sua origem seja confiável, mas não restringindo a visualização do código.","Marcar o arquivo como \"Final\" (Somente Leitura) nas propriedades do documento."],"correta":"C"},{"n":29,"disciplina":"Informática","tema":"Windows","enunciado":"Ao trabalhar com o Sistema Operacional Windows 10, um usuário precisa organizar os arquivos em seu computador, o que frequentemente envolve mover (recortar) ou copiar itens entre pastas. Para otimizar o tempo e evitar o uso do mouse ou menu de contexto, o uso de atalhos de teclado é essencial. Assinale a sequência de teclas de atalho padrão do Windows que deve ser utilizada, respectivamente, para recortar (mover) um arquivo ou pasta selecionado e, em seguida, colá -lo no novo local desejado.","alternativas":["Ctrl + S para recortar e Ctrl + V para colar.","Ctrl + X para recortar e Ctrl + V para colar.","Ctrl + C para copiar e Ctrl + P para colar.","Alt + F4 para recortar e Ctrl + X para colar.","Shift + Del para recortar e Ctrl + V para colar"],"correta":"B"},{"n":30,"disciplina":"Informática","tema":"Internet e Navegadores","enunciado":"No ambiente de Internet, a transferência de dados e arquivos entre o computador do usuário (cliente) e um servidor remoto é uma operação constante e fundamental, seja para acessar uma página, salvar um documento na nuvem ou baixar uma foto. Considerando a transferência de arquivos e dados, os termos técnicos que definem as ações de enviar um arquivo do seu computador local para um servidor (ex: salvando na nuvem) e a ação de receber um arquivo de um servidor para o seu computador (ex: baixando um documento) são, respectivamente,","alternativas":["Download e Streaming.","Upload e Download.","Streaming e Upload.","Banda e Upload.","Upload e Banda. Legislação do Estado do Amazonas"],"correta":"B"},{"n":41,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"O Sistema Único de Saúde (SUS) é estruturado para garantir o direito à saúde a toda a população brasileira, sendo orientado por princípios e diretrizes que norteiam sua organização e funcionamento. Considerando esses aspectos, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) A descentralização prevê que os serviços devem ser organizados em níveis crescentes de complexidade, circunscritos a uma determinada área geográfica. ( ) A equidade consiste em oferecer recursos de forma igualitária a todos os municípios, independentemente das diferenças epidemiológicas, socioeconômicas ou de vulnerabilidade populacional. ( ) A integralidade orienta o cuidado ao considerar o conjunto de necessidades de saúde do indivíduo, promovendo ações coordenadas entre diferentes níveis de atenção e entre promoção, prevenção, tratamento e reabilitação. Aa afirmativas são, respectivamente,","alternativas":["F – F – V.","V – F – V.","F – V – F.","F – F – F.","V – V – V"],"correta":"A"},{"n":42,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"A Política Nacional de Atenção à Saúde da Pessoa com Deficiência (PNSPCD) busca garantir cuidado integral, acessível e contínuo a indivíduos com diferentes tipos de deficiência, cujas ações estão organizadas em eixos de atuação. Assinale a opção que apresenta uma ou mais ações estratégicas do eixo “organização das ações e serviços de saúde sob a lógica das Redes de Atenção à Saúde”.","alternativas":["O estímulo à autonomia e à co-responsabilidade.","A articulação e a integração dos diferentes pontos de atenção.","O fortalecimento das ações de educação permanente nos serviços de saúde.","A tradução, a divulgação e a comunicação das informações em saúde.","A promoção da saúde, a qualidade de vida e a prevenção de agravos"],"correta":"B"},{"n":43,"disciplina":"Enfermagem","tema":"Segurança do Paciente","enunciado":"Durante a admissão de um pa ciente idoso na clínica médica, a enfermeira aplicou a Escala de Morse para avaliar o risco de queda. O paciente apresenta histórico de queda recente, usa medicação sedativa, necessita de auxílio para deambular e levanta -se frequentemente sem pedir ajuda. Considerando a interpretação dessa escala, o paciente deve receber a seguinte classificação:","alternativas":["ausência de risco de queda, pois a deambulação é mantida com mínima assistência.","risco leve de queda, sem necessidade de medidas específicas de precaução ambiental.","risco baixo de queda, exigindo apenas observação periódica e registro diário de Enfermagem.","risco moderado de queda, devendo ser reavaliado semanalmente pela equipe de Enfermagem.","risco alto de queda, necessitando implementação imediata de medidas preventivas intensivas."],"correta":"E"},{"n":44,"disciplina":"Enfermagem","tema":"Hanseníase","enunciado":"Durante uma ação de vigilância, a equipe de saúde realizou o acompanhamento dos contatos domiciliares de um paciente recentemente diagnosticado com hanseníase multibacilar. Os familiares relatam que conviviam com o paciente diariamente antes da confirmação da doença. Com base nas recomendações do Ministério da Saúde acerca da imunoprofilaxia e do monitoramento dessas pessoas, é correto afirmar que","alternativas":["o exame clínico é restrito aos contatos que apresentem lesões aparentes ou diminuição da sensibilidade, sendo dispensável para os assintomáticos.","recomenda-se aplicar a vacina BCG apenas nas crianças menores de 5 anos, independentemente do histórico vacinal anterior, e monitorar os demais.","o acompanhamento dos contatos deve ocorrer apenas após o término do tratamento do caso índice, para evitar resultados falso-positivos.","a vacina BCG deve ser administrada a todos os contatos, inclusive os que já receberam duas d oses documentadas anteriormente.","recomenda-se ofertar imunoprofilaxia aos contatos maiores de um ano de idade, não vacinados ou que receberam apenas uma dose da vacina BCG"],"correta":"E"},{"n":45,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"O planejamento estratégico e o planejamento normativo são instrumentos de gestão que orientam a formulação de políticas e ações organizacionais. Considerando as características desses dois tipos de planejamento, é correto afirmar que:","alternativas":["o planejamento estratégico é essencialmente prescritivo, voltado à definição de normas e padrões de conduta.","o planejamento normativo busca traduzir metas políticas em planos operacionais flexíveis, priorizando a adaptação ao ambiente externo.","o planejamento estratégico orienta a organização para o futuro com base em diagnósticos e cenários.","tanto o planejamento estratégico quanto o normativo são prospectivos e dinâmicos, com caráter estritamente técnico.","o planejamento normativo e o estratégico são equivalentes, pois ambos se concentram na execução operacional e no controle dos resultados organizacionais"],"correta":"C"},{"n":46,"disciplina":"Legislação do SUS","tema":"Redes de Atenção à Saúde","enunciado":"O hospital-dia é uma modalidade assistencial inserida na Rede de Atenção à Saúde que visa otimizar o cuidado e o uso de recursos hospitalares. Considerando suas características, é correto afirmar que o hospital-dia","alternativas":["destina-se a internações que durem até 24 horas, voltadas à reabilitação intensiva de pacientes com doenças crônicas.","oferece cuidados intermediários entre a internação integral e o atendimento ambulatorial, com permanência máxima de 12 horas diárias.","é voltado para a pacientes psiquiátricos, funcionando como substitutivo das internações hospitalares prolongadas.","é voltado para procedimentos cirúrgicos de média complexidade, com necessidade de acompanhamen to multiprofissional contínuo.","é um serviço de pronto atendimento destinado a casos de urgência e emergência que não demandam internação prolongada"],"correta":"B"},{"n":48,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Com base nos protocolos do Ministério da Saúde, conforme tratamento profilático da deficiência de ferro em gestantes (com Hb > 11 g/dL e ferritina ≥ 30 ng/mL), é correto afirmar que","alternativas":["a dose diária não deve ultrapassar 2 00 µg de ácido fólico, devendo ser suspensa após o parto.","a suplementação deve ser mantida por até 2 meses após o parto, apenas para mulheres que tiveram parto normal.","a dose diária no pós -parto deve ser de 60 a 100 mg de ferro elementar + 400 µg de ácido fólico.","a suplementação deve ser iniciada a partir da 30ª semana de gestação, independentemente do estado nutricional.","a dose diária deve ser de 100 a 200 mg de ferro elementar durante toda a gestação"],"correta":"C"},{"n":49,"disciplina":"Enfermagem","tema":"Diabetes Mellitus","enunciado":"Em pacientes com diabe tes, o controle glicêmico deve ser individualizado de acordo com a situação clínica. Nesse sentido, para um paciente com Diabetes Mellitus tipo 2, a meta para glicemia em jejum é","alternativas":["< 80 mg/dL.","entre 70-99mg/dL.","entre 80-130mg/dL.","entre 90-150mg/dL.","entre 99-140mg/dL"],"correta":"C"},{"n":50,"disciplina":"Enfermagem","tema":"Tuberculose","enunciado":"Durante o tratamento da Tuberculose Pulmonar, o paciente deve ser orientado a respeito das reações adversas relacionadas aos fármacos do esquema básico. Nesse caso, assinale a opção que corresponde ao fármaco associado à ocorrência prurido e exantema leve:","alternativas":["isoniazida.","etambutol.","terizidona.","pirazinamida.","levofloxacino."],"correta":"A"},{"n":51,"disciplina":"Enfermagem","tema":"Imunização","enunciado":"Uma criança de 4 anos, com todas as vacinas em dia, foi levada à unidade de saúde para atualização vacinal rotineira. De acordo com o Calendário Nacional de Vacinação, as doses recomendadas nessa faixa etária incluem","alternativas":["tríplice bacteriana - DTP (2º reforço), febre amarela (reforço) e varicela (2ª dose).","tríplice viral (1ª dose), meningocócica C (reforço) e hepatite B (3ª dose).","pneumocócica 10 -valente (reforço), rotavírus (2ª dose) e influenza sazonal.","hepatite A (1ª dose), influenza (reforço) e HPV quadrivalente (1ª dose).","febre amarela (1ª dose), tríplice viral (2ª dose) e varicela (1ª dose)"],"correta":"A"},{"n":52,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"A Classificação Internacional para a Prática de Enfermagem (CIPE) organiza seus conceitos em eixos que permitem a formulação de enunciados diagnósticos, intervenções e resultados de Enfermagem. Considerando essa taxonomia de Enfermagem, é correto afirmar que:","alternativas":["a estrutura da CIPE é organizada por sistemas corporais e patologias, similar ao modelo da Classificação Internacional de Doenças (CID).","os eixos da CIPE se restringem à descrição de doenças e agravos clínicos, sem incluir fatores relacionados ao ambiente e ao cliente.","a CIPE utiliza eixos voltados apenas para registro de procedimentos técnicos e aspectos operacionais do cuidado de Enfermagem.","os eixos da CIPE correspondem às dimensões do processo administrativo de Enfermagem: planejamento, execução e avaliação.","os eixos da CIPE incluem foco, julgamento, ação, cliente, localização, tempo e meio, compondo a base combinatória para expressar fenômenos e ações de Enfermagem"],"correta":"E"},{"n":53,"disciplina":"Enfermagem","tema":"Saúde Mental","enunciado":"Durante uma visita domiciliar, um homem de 28 anos diz ouvir vozes que o insultam, demonstra fala desorganizada, comportamento retraído e pouca expressão emocional. Segundo familiares, o quadro vem se mantendo há cerca de oito meses, com dificuldade para manter autocuidado e vínculos sociais. Considerando o caso descrit o, os sinais apresentados são característicos de","alternativas":["transtorno dissociativo, caracterizado por perda temporária da identidade e lacunas de memória episódica.","transtorno de pânico, caracterizado por episódios agudos de medo intenso e sintomas físicos transitórios.","transtorno afetivo bipolar, caracterizado por alternância entre fases de euforia e períodos de humor deprimido.","transtorno obsessivo -compulsivo, caracterizado por pensamentos intrusivos e comportamentos repetitivos de verificação.","esquizofrenia, caracterizada por delírios, alucinações, discurso desorganizado e prejuízo funcional persistente"],"correta":"E"},{"n":54,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Durante a administração de quimioterapia intravenosa com um antineoplásico pertencente ao grupo alcaloides da vinca, a paciente referiu ardência e dor intensa no local da punção , além de edema e eritema ao redor da veia. Diante dessa situação, a conduta imediata mais adequada é","alternativas":["massagear vigorosamente o local do extravasamento, para dispersar o quimioterápico e acelerar absorção pelos tecidos.","reduzir a velocidade da infusão, aplicar compressa fria e continuar a administração do quimioterápico até o término.","suspender o tratamento e encaminhar a paciente para observação, mantendo o acesso venoso com soro fisiológico.","interromper imediatamente a infusão, aspirar o extravasado, e aplicar compressa morna.","retirar imediatamente o acesso venoso sem aspirar o extravasado e manter o membro elevado"],"correta":"D"},{"n":55,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um paciente chega à emergência com palpitações. O ECG apresenta ritmo regular, ondas P visíveis antes de cada QRS e intervalo R -R, medindo aproximadamente 4 quadradinhos grandes. Utilizando a regra dos 300, a frequência cardíaca estimada é","alternativas":["60 bpm.","75 bpm.","90 bpm.","100 bpm.","120 bpm"],"correta":"B"},{"n":56,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Uma paciente de 32 anos deu entrada na unidade de saúde apresentado dor abdominal intensa no quadrante inferior direito, associada a náuseas e febre de 38°C. Durante o exame físico, ao realizar palpação profunda na fossa ilíaca direita, a paci ente relatou dor acentuada à descompressão súbita. A manifestação clínica descrita corresponde ao sinal de","alternativas":["Cullen.","Rovsing.","Murphy.","Blumberg.","McBurney"],"correta":"D"},{"n":57,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante a assistência a um paciente em ventilação mecânica, o enfermeiro utilizou a Escala de Sedação de Ramsay para avaliar o nível de sedação. Considerando a aplicação e interpretação dessa escala, é correto afirmar que a Escala de Ramsay","alternativas":["classifica seis níveis de sedação (1 a 6), em que 1 é alerta e 6 sem resposta.","classifica seis níveis de sedação (0 a 5), sendo 0 o mais leve e 5 o mais profundo.","classifica a intensidade da dor, sendo utilizada para avaliação analgésica em pacientes críticos.","inclui avaliação do tamanho pupilar e da reatividade fotomotora, somando pontos ao escore total.","considera que escore mais alto corresponde à maior vigilância e melhor resposta verbal do paciente."],"correta":"A"},{"n":58,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Com base nas Diretrizes Nacionais de Assistência ao Parto Normal e das boas práticas recomendadas pelo Ministério da Saúde, é correto afirmar, segundo a assistência ao parto de baixo risco, que","alternativas":["a realização de manobras uterinas, como a pressão de fundo (manobra de Kristeller), é indicada rotineiramente para acelerar a saída do feto e prevenir hemorragias.","a episiotomia rotineira é recomendada para todas as parturientes como medida preventiva de lacerações perineais.","a ocitocina deve ser administrada na parturiente logo após o nascimento do bebê, por via intramuscular, para favor ecer a contração uterina e reduzir o risco de hemorragia pós-parto.","entre as técnicas recomendadas para prevenir a demora no trabalho de parto estão a amniotomia precoce e o uso de agentes antiespasmódicos.","tricotomia e enema, antes do trabalho de parto são práticas recomendadas de rotina para reduzir infecções e facilitar o nascimento"],"correta":"C"},{"n":59,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Considerando o Programa de Humanização no Pré -natal e Nascimento (PHPN) e as recomendações do Ministério da Saúde sobre a assistência ao recém-nascido, é correto afirmar que","alternativas":["o clampeamento imediato do cordão umbilical é recomendado para prevenir icterícia neonatal e melhorar a oxigenação cerebral do recém-nascido.","a aspiração das vias aéreas do recém -nascido deve ser realizada de forma rotineira, mesmo sem sinais de obstrução, para prevenir broncoaspiração.","o banho do recém -nascido deve ser realizado logo após o parto, com o objetivo de remover vérnix caseoso e prevenir infecções cutâneas.","a administração de vitamina K é indicada apenas para prematuros com baixo peso, sendo desnecessária em recém - nascidos a termo e saudáveis.","a profilaxia da oftalmia neonatal deve ser realizada rotineiramente com pomada de eritromicina a 0,5% e, como alternativa, tetraciclina a 1%"],"correta":"E"},{"n":60,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Com base nas diretrizes para a Terapia de Reposição Hormonal (TRH), durante Climatério e Menopausa, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) A TRH deve ser iniciada nos primeiros 10 anos após o início da menopausa, ou antes dos 60 anos, para que os benefícios cardiovasculares superem os riscos. ( ) A TRH é contraindicada em mulheres com hipertensão arterial controlada, mesmo quando os riscos cardiovasculares estão avaliados e monitorados. ( ) Mulheres com histórico de câncer de mama podem realizar TRH, desde que tenha se passado mais de 5 anos do fim do tratamento. As afirmativas são, respectivamente,","alternativas":["F – F – F.","V – F – F.","F – V – V.","V – V – V.","F – V - F"],"correta":"B"},{"n":61,"disciplina":"Enfermagem","tema":"Administração de Medicamentos e Cálculos","enunciado":"Após receber a administração de metoclopramida (plasil) por via intravenosa, um paciente adulto começou a apresentar tremores nas extremidades dos membros superiores, rigidez muscular, inquietação intensa, movimentos involun tários da língua e face, além de dificuldade para manter-se imóvel. Esse quadro é característico de","alternativas":["reação anafilática causada por hipersensibilidade medicamentosa.","crise colinérgica decorrente da estimulação parassimpática excessiva.","efeito e xtrapiramidal induzido por antagonismo dopaminérgico central.","reação serotoninérgica relacionada ao excesso de neurotransmissores.","síndrome neuroléptica maligna provocada por disfunção autonômica grave"],"correta":"C"},{"n":62,"disciplina":"Legislação do COFEN","tema":"Responsabilidade Profissional","enunciado":"Durante a prestação de cuidad os a um paciente hospitalizado, o profissional de Enfermagem administrou uma medicação incorreta, ocasionando uma reação adversa que provocou perigo de morte, embora o paciente tenha se recuperado após atendimento emergencial. De acordo com o Código de Ética dos Profissionais de Enfermagem, essa conduta configura uma infração","alternativas":["leve.","grave.","severa.","moderada.","gravíssima"],"correta":"B"},{"n":63,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um paciente de 40 anos sofreu acidente automobilístico e chegou à unidade de saúde apresentando equimoses periorbitais em “olhos de guaxinim”, hemotímpano, rinorreia e otorreia com líquido claro, além de diplopia leve e confusão mental. Os sinais e sintomas apresentados são característicos de","alternativas":["hematoma epidural.","hematoma subdural.","fratura de base de crânio.","ratura linear de calvária.","contusão cerebral difusa"],"correta":"C"},{"n":64,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente de 68 anos, com história de insuficiência cardíaca congestiva, é admitido em uma unidade de saúde apresentando confusão mental, fraqueza muscular e náuseas. Está em uso de furosemida 40 mg duas vezes ao dia. Ao exame físico, apresenta pressão arterial de 95/60 mmHg, turgor diminuído e mucosas secas. Os sin ais apresentados são característicos do seguinte distúrbio hidroeletrolítico:","alternativas":["hipocalemia.","hipercalemia.","hipocalcemia.","hiponatremia.","hipernatremia."],"correta":"D"},{"n":65,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um homem de 54 anos, com história de DPOC grave e uso irregular de bronc odilatadores, é admitido na emergência por dispneia intensa, sonolência e confusão mental. Ao exame, está cianótico, com frequência respiratória de 10 irpm e uso de musculatura acessória. Resultado da gasometria arterial em ar ambiente: pH: 7,26 PaCO₂: 68 mmHg HCO₃⁻: 30 mEq/L PaO₂: 52 mmHg Com base nesses achados, assinale o distúrbio ácido -básico predominante e seu mecanismo compensatório.","alternativas":["Acidose respiratória parcialmente compensada por retenção renal de bicarbonato.","Alcalose respiratória parci almente compensada por eliminação de bicarbonato.","Acidose metabólica compensada por hiperventilação e eliminação de CO₂.","Alcalose metabólica compensada por hipoventilação e retenção de CO₂.","Acidose respiratória totalmente compensada por mecanismos renais imediatos"],"correta":"A"},{"n":66,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante a assistência a um paciente adulto em ventilação mecânica invasiva por insuficiência respiratória aguda, a equipe de Enfermagem deve adotar cuidados para prevenir complicações e promover segurança do paciente. Nesse sentido, assinale a conduta correta.","alternativas":["Manter o paciente em decúbito dorsal plano para otimizar o retorno venoso e evitar instabilidade hemodinâmica.","Realizar aspiração traqueal rotineiramente em horários fixos, independentemente da necessidade clínica observada.","Garantir pressão do cuff entre 50 e 60 cmH₂O, para evitar escape de ar e reduzir o risco de pneumonia associada à ventilação.","Elevar a cabeceira do leito entre 30° e 45°, realizar higiene oral com antisséptico e manter sistema fechado de aspiração.","Suspender a higiene oral durante períodos de instabilidade respiratória, para evitar aumento do esforço ventilatório e risco de dessaturação"],"correta":"D"},{"n":67,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante o atendimento de um paciente masculino, 45 anos, vítima de acidente de trânsito com trauma craniano fechado, foram verificadas: • abertura ocular: abre apenas ao estímulo doloroso; • resposta verbal: sons incompreensíveis; • resposta motora: retira o membro ao estímulo doloroso; • reatividade pupilar: uma pupila não reage à luz. Com base nos parâmetros da Escala de Coma de Glasgow com Resposta Pupilar (ECG-P), as respostas apresentadas na avaliação correspondem à seguinte pontuação:","alternativas":["6 pontos.","7 pontos.","8 pontos.","9 pontos.","10 pontos"],"correta":"B"},{"n":68,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"Um Centro de Atenção Psicossocial (CAPS II) funciona 8 horas por dia, atendendo, em média, 40 usuários por turno, com predominância de cuidados de média complexidade e atendimentos em grupo. De acordo com as recomendações do COFEN, assinale a opção que representa a quantidade adequada mínima de profissionais de Enfermagem por turno.","alternativas":["1 enfermeiro e 1 técnico de Enfermagem.","1 enfermeiro e 2 técnicos de Enfermagem.","1 enfermeiro e 3 técnicos de Enfermagem.","2 enfermeiros e 2 técnicos de Enfermagem.","2 enfermeiros e 3 técnicos de Enfermagem"],"correta":"D"},{"n":69,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante o atendimento de um homem de 60 anos, encontrado inconsciente e sem pulso em ambiente hospitalar, a equipe inicia o protocolo de ressuscitação. Após 2 minutos de RCP, o monitor mostra assistolia persistente. Com base nas Diretrizes de Ressuscitação Cardiopulmonar, a conduta recomendada é","alternativas":["interromper a RCP por 10 segundos para checar o ritmo, realizar desfibrilação e administrar 300 mg de amiodarona EV.","suspender a RCP e iniciar ventilação isolada com ambu, pois a assistolia não responde à compressão torácica.","continuar a RCP por mais 2 minutos, administrar 1 mg de epinefrina a cada 3–5 minutos e reavaliar o ritmo após o ciclo.","aplicar desfibrilação imediata e iniciar amiodarona EV, pois a ausência de pulso indica ritmo chocável.","realizar pausa prolongada para verificar pulso e respiração, iniciando RCP apenas após nova confirmação da parada"],"correta":"C"},{"n":70,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Um agri cultor de 40 anos foi conduzido à Unidade de Pronto Atendimento, com quadro de salivação intensa, sudorese, miose acentuada, bradicardia e dificuldade respiratória, após aplicar inseticida em sua plantação sem o uso adequado de EPIs. O quadro clínico é compatível com intoxicação por organofosforados. Nesse caso, o antidoto adequado é","alternativas":["naloxona.","atropina.","flumazenil.","hidroxocobalamina.","bicarbonato de sódio"],"correta":"B"},{"n":71,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"Durante o processo anual de avaliação de desempenho de um coordenador, a organização aplicou o seguinte procedimento: o avaliado respondeu um formulário de autoavaliação; o gestor direto aplicou uma escala por competências; três colegas do mesmo nível e dois subordinados preencheram formulários padronizados; e o resultado consolidado foi devolvido ao avaliado em feedback individual, com plano de desenvolvimento. A descrição apresentada corresponde à seguinte ferramenta de avaliação","alternativas":["matriz 9 box.","avaliação 90°.","avaliação 180°.","avaliação 360°.","avaliação por competência."],"correta":"D"},{"n":72,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"Uma unidade de saúde decidiu realizar uma auditoria interna para verificar a conformidade dos processos assistenciais. O trabalho foi realizado in loco , durante o atendimento, com foco em alguns aspectos específicos. Essa forma de auditoria é denominada","alternativas":["analítica.","preventiva.","concorrente.","prospectiva.","retrospectiva"],"correta":"C"},{"n":73,"disciplina":"Enfermagem","tema":"Gerenciamento de Resíduos de Serviços de Saúde (GRSS)","enunciado":"Com base nas disposições quanto ao gerenciamento de resíduos de serviços de saúde – RSS, analise as afirmativas a seguir e assinale V para a verdadeira e F para a falsa. ( ) Os resíduos perfurocortantes são considerados categoria A, pois apresentam risco biológico, podendo causar perfuração ou contaminação. ( ) A identificação dos sacos para acondicionamento dos R SS do grupo D deve estar impressa, sendo vedado o uso de adesivo. ( ) Os RSS, gerados pelos serviços de atenção domiciliar, devem ser acondicionados e recolhidos pelos próprios agentes de atendimento, além de encaminhados à destinação final ambientalmente adequada. As afirmativas são, respectivamente,","alternativas":["F – V – V.","V – F – F.","F – F – V.","V – V – V.","F – V – F"],"correta":"C"},{"n":74,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Uma pesquisadora deseja investigar se a prática regular de atividade física está associada à redução dos níveis de estresse em estudantes universitários. Para garantir clareza metodológica, ela precisa definir adequadamente as variáveis do estudo. Nesse caso, é correto afirmar que","alternativas":["nenhuma das variáveis deve ser definida antes da coleta, para não interferir nos resultados.","o nível de estresse é uma variável independente, e a prática de atividade física é a variável dependente.","ambas as variáveis são dependentes, pois podem variar conforme o humor dos participantes.","as duas variáveis são independentes, já que uma não influencia a outra diretamente.","a prática regular de atividade física é uma variável independente, e o nível de estresse é a variável dependente"],"correta":"E"},{"n":75,"disciplina":"Enfermagem","tema":"Ética e Legislação em Enfermagem","enunciado":"Ao orientar uma família acerca da doação de órgão, o profissional de saúde explicou que, de acordo com a legislação brasileira vigente, a retirada de órgãos para fins de transplante só pode ocorrer após","alternativas":["autorização verbal do familiar de primeiro grau do paciente.","confirmação clínica do óbito por parada cardiorrespiratória.","solicitação formal do médico responsável pelo atendimento.","consentimento familiar por escrito e confirmação da morte encefálica.","autorização judicial emitida por perito do tribunal competente"],"correta":"D"},{"n":76,"disciplina":"Enfermagem","tema":"Centro de Material e Esterilização (CME)","enunciado":"O monitoramento é etapa essencial para garantir eficácia, qualidade e segurança do processo de esterilização de produtos para a saúde. Considerando as disposições normativas a esse respeito é correto afirmar que","alternativas":["o monitoramento do processo de esterilização com indicador biológico deve ser feito diariamente, em todas as cargas, em pacote teste desafio.","é possível substituir o uso rotineiro de indicadores biológicos por integradores químicos classe 5, já que ambos avaliam simultaneamente os parâmetros críticos do processo.","o teste para avaliar o desempenho do sistema de remoção de ar (Bowie & Dick) da autoclave assistida por bomba de vácuo é recomendado apenas em situações de urgência e emergência.","o monitoramento com integradores químicos classe 5 ou 6 só deve ser realizado em situações críticas, quando houver falhas nos testes rotineiros.","no monitoramento do processo de esterilizaçã o dos produtos implantáveis para saúde, deve ser adicionado um indicador biológico, a cada carga"],"correta":"E"},{"n":77,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Durante a assistência a um paciente hospitalizado com suspeita de meningite meningocócica, o profissional de saúde deve adotar medidas de prev enção compatíveis com a forma de transmissão da doença, de modo a evitar a disseminação do agente infeccioso. Nessa situação, considerando a forma de transmissão, a precaução indicada é","alternativas":["padrão, pois a transmissão ocorre apenas pelo contato com superfícies contaminadas, sem necessidade de máscara.","contato, pois o agente etiológico é transmitido por meio do toque direto com secreções ou pele não íntegra do paciente.","gotícula, pois o agente é transmitido por secreções respiratórias expelidas ao fal ar, tossir ou espirrar a curta distância.","aerossol, pois o agente permanece suspenso no ar por longos períodos, exigindo isolamento com pressão negativa.","reforçada, pois a doença requer a combinação obrigatória de precauções padrão, de contato e po r aerossóis simultaneamente"],"correta":"C"},{"n":78,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante a abordagem de um paciente em parada cardiorrespiratória, o enfermeiro precisou utilizar um dispositivo extraglótico (DEG) do tipo supraglótico para manutenção da via aérea avançada. Um exemplo desse tipo de dispositivo é:","alternativas":["tubo laríngeo.","cânula faríngea.","máscara laríngea.","cateter orofaríngeo.","tubo traqueo-esofágico."],"correta":"C"},{"n":79,"disciplina":"Enfermagem","tema":"Controle de Infecção e Biossegurança","enunciado":"Após a realização de um procedimento cirúrgico, um paciente adulto foi diagnosticado com infecção de sítio cirúrgico incisional superficial. Entre os critérios que caracterizam esse tipo de infecção, está a","alternativas":["presença de eritema, calor, dor local ao red or da incisão, ocorrendo até 30 dias após a cirurgia , com ou sem drenagem purulenta.","inflamação envolvendo músculo ou fáscia, com abscesso profundo, ocorrendo em até 30 dias após a cirurgia.","infecção limitada ao órgão ou espaço interno, sem envolvimento da incisão cirúrgica, ocorrendo até 90 dias após a cirurgia.","presença de febre isolada, sem eritema, dor ou secreção na incisão, ocorrendo até 45 dias após a cirurgia.","presença de febre, abcesso ou deiscência espontânea, ocorrendo até 20 dia s após a cirurgia, com drenagem purulenta"],"correta":"A"},{"n":80,"disciplina":"Enfermagem","tema":"Centro Cirúrgico","enunciado":"Durante um procedimento cirúrgico, o profissional responsável inicia a aplicação da Lista de Verificação de Segurança Cirúrgica (checklist de cirurgia segura). De acordo com o Protocolo de Cirurgia Segura do Ministério da Saúde, assinale a afirmativa que corresponde às ações que devem ser obrigatoriamente realizadas, antes da indução anestésica, na etapa denominada “Sign In”.","alternativas":["Realizar contagem de compressas e instrumentais e checar antibiótico profilático.","Revisar o nome completo do paciente, o consentimento informado e o local da cirurgia.","Validar o registro do horário de início da cirurgia e assegurar a presença de exames complementares.","Confirmar o funcionamento do aspirador cirúrgico, a disponibilidade de drenos e o preparo dos campos estéreis.","Realizar o registro da equipe no prontuário e validar a conferência do material."],"correta":"B"}]},{"codigo":"tjms-enfermeiro-2026","ano":2026,"orgao":"Tribunal de Justiça do Estado de Mato Grosso do Sul","cargo":"Técnico de Nível Superior — Enfermagem","prova":"https://conhecimento.fgv.br/sites/default/files/concursos/tecnico-de-nivel-superior-enfermagem-cns102-tipo-1.pdf","gabarito":"https://conhecimento.fgv.br/sites/default/files/concursos/tjms-analista-e-tecnico.pdf","itens":[{"n":1,"disciplina":"Língua Portuguesa","tema":"Ortografia e Acentuação","enunciado":"A pronúncia correta das palavras e sua escrita adequada são partes importantes do ensino e da prática da Língua Portuguesa. As opções a seguir apresentam frases com palavras sub linhadas e, sobre cada uma dessas palavras, aparece uma observação sobre a sua pronúncia. Assinale a opção cuja observação está correta.","alternativas":["A polícia britânica informou neste sábado a prisão de 31 pessoas em um protesto contra o fundamentalismo islâmico e o fascismo na cidade de Birmingham, no centro da Inglaterra. (Folha de São Paulo, 09/08/2009). Por ser palavra de origem italiana, a pronúncia adequada desse vocábulo deve ser “fachismo”.","A construção tem o formato de um condor, ave símbolo de força e liberdade para os moradores dos Andes. ( Folha de São Paulo, 07/07/2011). A pronúncia correta desse vocábulo é como palavra paroxítona – condor – e não como oxítona - condor.","O filantropo anônimo viajou dos Estados Unidos para a Austrália no ano passado para doar o quadro do gênio cubista. ( Folha de São Paulo, 27/04/2011). A palavra destacada deve ser pronunciada como proparoxítona (filantropo) e não como paroxítona (filantropo).","Deve-se dar à criança o direito ao ensino gratuito. ( Unicef, 2013). Deve-se pronunciar UI (gra -tui-to) como ditongo e não como hiato (gra-tu-í-to).","Sem saber como contratar os novos músicos, o teatro passou a incluí -los na rubrica que estava à mão : “verbas de terceiros”, uma forma destinada, exclusivamente, à contratação temporária. ( Folha de São Paulo. 10/07/2009). A palavra é proparoxítona (rubrica) e não paroxítona (rubrica)"],"correta":"D"},{"n":4,"disciplina":"Língua Portuguesa","tema":"Figuras de Linguagem e Vícios de Linguagem","enunciado":"As opções a seguir apresentam frases em que foram empregadas construções redundantes, à exceção de uma. Assinale-a.","alternativas":["Aos 80 anos, o escritor decidiu escrever sua autobiografia.","Politicamente, o Brasil está dividido em duas metades.","Na opinião abalizada deles, não irá chover no Natal.","O pelotão decidiu avançar para a frente.","A turma saiu devagar, sem pressa, para o recreio"],"correta":"C"},{"n":8,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"Assinale a frase em que o galicismo (palavra de origem francesa) empregado tem seu equivalente em língua portuguesa corretamente indicado.","alternativas":["As meninas de hoje deixaram de usar rouge, mas continuam usando pó-de-arroz. / maquiagem.","A sala possuía um abat-jour sobre todas as mesinhas. / quebra-luz.","Os carros eram deixados na garage do prédio. / depósito.","Os filés eram acompanhados de patê de fígado. / molho.","A viúva usava um robe de chambre muito elegante. / sobretudo"],"correta":"B"},{"n":12,"disciplina":"Língua Portuguesa","tema":"Interpretação de Textos","enunciado":"Sobre a organização estrutural e a significação dos termos presentes no texto, assinale a afirmativa correta.","alternativas":["Marco Nanini aparece sem qualquer identificação porque o autor do texto considera que os leitores não o identificarão, por já ser ator antigo.","Lady Enid não vem acompanhada de um termo identificador porque se trata de personagem desconhecido, não sendo importante no texto.","A conjunção “Mas”, sendo adversativa, tem a função de negar o que foi dito ant eriormente – “Estamos sendo perseguidos por fantasmas e espíritos”.","O termo “o ator” aparece como sinônimo do termo “Marco Nanini”, citado antes.","O advérbio “naturalmente” valoriza o ator citado, por sua presença de espírito. XI"],"correta":"E"},{"n":14,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"Assinale a opção que apresenta a frase em que a preposição entre tem o valor semântico de indicar posição intermediária entre dois pontos.","alternativas":["Havia muito riso, muito parolar de papagaios; pequenos travessavam, tão depressa rindo como chorando; os italianos faziam a ruidosa digestão dos seus jantares de festa; ouviam - se cantigas e pragas entre gargalhadas. (O Cortiço)","E fazendo do resto do seu dinheiro um bolo, que ele, um pouco ébrio, apertava nos dedos, agora, claros e quase descalejados, socou-o na algibeira do lado direito explicando entre dentes que ali ficava ainda bastante para o que desse e viesse, no caso de algum contratempo. (O Cortiço)","— Sei-o eu lá se me morreu?... disse Piedade entre soluços. Vi tanta coisa esta noite!... (O Cortiço)","A mulata então aproximou -se dele, por detrás; segurou -lhe a cabeça entre as mãos e beijou -o na boca, arredando com os lábios a espessura dos bigodes. (O Cortiço)","O Barão e o Botelho apareciam por lá quase todos os dias; examinavam os materiais escolhidos para a construção, batiam com a biqueira do chapéu de sol n o pinho -de-riga destinado ao assoalho, e afetando -se bons entendedores, tomavam na palma da mão e esfarelavam entre os dedos um punhado da terra e da cal com que os operários faziam barro. (O Cortiço)"],"correta":"D"},{"n":15,"disciplina":"Língua Portuguesa","tema":"Semântica e Significação","enunciado":"As opções a seguir apresentam frases que utilizam o verbo haver em lugar de outro, que tenha significado mais específico. Assinale a opção em que a substituição de haver por outro verbo é feita de forma adequada.","alternativas":["Dizem que haverá eleições antes do previsto. / ocorrerão.","Naquela reunião houve apreciações bem diferentes. / trouxeram.","A meteorologia afirma que haverá sol no final de semana. / acontecerá.","Lá longe, atrás da montanha, há uma igreja. / surge.","As estatísticas mostram que, a cada dia, há mais gent e nos estádios de futebol. / assiste. Noções de Legislação"],"correta":"A"},{"n":21,"disciplina":"Legislação do COFEN","tema":"Registros de Enfermagem","enunciado":"O prontuário do paciente, reconhecido como um documento oficial, é um instrumento essencial na assistência à saúde, ao listar os registros assistenciais e administrativos relacionados ao cuidado prestado. Considerando seus aspectos legais, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O prontuário do paciente possui val or jurídico e pode ser utilizado como prova em processos éticos, administrativos e judiciais. ( ) O prontuário do paciente tem caráter sigiloso, e, por isso, não pode ser solicitado por autoridades judiciais ou órgãos fiscalizadores. ( ) O prontuário d o paciente é um documento administrativo, sem valor jurídico, devendo ser utilizado apenas para fins internos da instituição de saúde. As afirmativas são, respectivamente,","alternativas":["F – F – F.","V – V – V.","F – V – V.","V – F – F.","F – V – F. XI"],"correta":"D"},{"n":22,"disciplina":"Legislação do COFEN","tema":"Código de Ética dos Profissionais de Enfermagem","enunciado":"Um profissional de Enfermagem foi intimado como testemunha para prestar depoimento acerca de fatos que teve conhecimento durante a atividade profissional. Sobre o caso narrado, com base no Código de Ética de Enfermagem, assinale a afirmativa correta.","alternativas":["O profissional deve manter o sigilo das informações, podendo revelar os fatos quando houver determinação judicial ou o consentimento escrito do paciente.","O profissional deve recusar -se a comparecer ao depoimento, alegando o dever de manter o s igilo profissional em qualquer circunstância.","O profissional pode divulgar informações sigilosas sempre que convocado como testemunha, sem necessidade de respaldo legal.","O profissional é obrigado a revelar todas as informações solicitadas, independentemente de autorização prévia do paciente.","O profissional deve comparecer ao depoimento e declarar a obrigação do sigilo profissional, mesmo com autorização do paciente"],"correta":"A"},{"n":23,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"As características definidoras de um dia gnóstico de enfermagem, segundo a taxonomia da NANDA-I, podem ser definidas como","alternativas":["fatos ou influências que têm certo tipo de relação com o diagnóstico.","influências que aumentam a vulnerabilidade de indivíduo a um evento não saudável.","dados subje tivos e objetivos coletados na avaliação de enfermagem que sustentam a identificação do diagnóstico.","indicadores observáveis que se agrupam como manifestações de um diagnóstico.","enunciados conceituais padronizados que descrevem o significado clínico do diagnóstico proposto"],"correta":"D"},{"n":24,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"A Sistematização da Assistência de Enfermagem (SAE) é fundamental para a organização do trabalho do enfermeiro e para a qualidade do cuidado prestado. Considerando os princípios e as finalidades da SAE, assinal e a afirmativa correta.","alternativas":["A SAE organiza o trabalho da enfermagem por meio de métodos, pessoal e instrumentos, viabilizando a aplicação do Processo de Enfermagem.","A SAE abrange o registro e o planejamento das ações de enfermagem, não incluindo etapas de avaliação e diagnóstico.","A SAE é recomendada, porém facultativa aos serviços de saúde, sendo obrigatória apenas em instituições de ensino e pesquisa.","A SAE constitui uma concepção teórica do processo de enfermagem, não interferindo na prática a ssistencial ou na rotina do cuidado.","A SAE é aplicada exclusivamente em ambientes hospitalares, não sendo usada na atenção básica, ambulatorial ou em outros níveis de atenção à saúde"],"correta":"A"},{"n":25,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"De acordo com os conceitos relacionados aos parâmetros de dimensionamento da força de trabalho da Enfermagem , um paciente considerado de “cuidados intermediários” é aquele que apresenta um quadro","alternativas":["estável, sob o ponto de vista clínico e de enfermagem, e autossuficiente quanto ao atendimento das necessidades humanas básicas.","estável, sob o ponto de vista clínico, porém com total dependência das ações de enfermagem para o atendimento das necessidades humanas básicas.","estável, sob o ponto de vista clínico e de enfermagem, com parcial dependência dos profissionais de Enfermagem para o atendimento das necessidades humanas básicas.","passível de instabilidade das funções vitais, recuperável, sem risco iminente de morte, requerendo assistência d e Enfermagem e médica permanente e especializada.","grave e recuperável, com risco iminente de morte, sujeito à instabilidade das funções vitais, requerendo assistência de Enfermagem e médica, permanente e especializada"],"correta":"C"},{"n":26,"disciplina":"Enfermagem","tema":"Processo de Enfermagem e SAE","enunciado":"Sobre as etapa s de planejamento e de implementação, etapas essenciais para garantir a efetividade da assistência de Enfermagem, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O planejamento de enfermagem envolve a priorização d os diagnósticos, a determinação dos resultados esperados e a tomada de decisão terapêutica por meio da prescrição de enfermagem. ( ) A implementação de enfermagem compreende a avaliação dos resultados alcançados e a execução direta das intervenções prescritas. ( ) Tanto a etapa de planejamento como a de implementação devem ser continuamente reavaliadas e ajustadas, conforme a resposta do paciente, garantindo a coerência entre o que foi prescrito e o cuidado efetivamente realizado. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – F – F.","V – V – F.","F – V – F.","V – V – V. XI"],"correta":"A"},{"n":27,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"O controle da validade de medicamentos e insumos é uma atividade essencial para a segurança do paciente e para a eficiência da gestão em saúde. Considerando as metodologias de gestão aplicadas no controle de estoques , avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O método Just in Time elimina a necessidade de controle rígido de validade, uma vez que os medicamentos são adquiridos apenas quando há demanda imediata de consumo. ( ) A utilização do método PEPS (Primeiro que Entra, Primeiro que Sai) no armazenamento de medicamentos e insu mos contribui para a redução de perdas por vencimento e para a segurança do uso dos produtos. ( ) O controle por lote e a rastreabilidade dispensam a padronização de processos, pois a identificação individual dos produtos é suficiente para a gestão do estoque. As afirmativas são, respectivamente,","alternativas":["F – F – V.","V – F – F.","F – V – V.","V – V – V.","F – V – F"],"correta":"E"},{"n":28,"disciplina":"Legislação do COFEN","tema":"Responsabilidade Profissional","enunciado":"Durante seu plantão em uma instituição pública de saúde, o profissional de enfermagem recusou -se a ser filmado enquanto desempenhava suas atividades, para exposição nas mídias sociais de um político. As filmagens foram autorizadas pela direção da instituição. Nesse caso, de acordo com o Código de Ética de Enfermagem, o profissional","alternativas":["cometeu uma falta ética, tend o em vista que se trata de uma instituição pública, podendo ser filmado ou fotografado por qualquer cidadão.","tem o direito de negar -se a ser filmado, fotografado e exposto em mídias sociais durante o desempenho de suas atividades profissionais.","pode ser filmado, desde que a divulgação tenha finalidade de promoção institucional, independentemente de sua autorização prévia.","cometeu um ato de desobediência funcional, podendo resultar em sanções administrativas por ir de encontro à autorização dada por superiores.","deve autorizar a filmagem presumida no exercício da função pública, não sendo necessária manifestação expressa de concordância"],"correta":"B"},{"n":29,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"A taxa de mortalidade infantil é um indicador referente ao número de óbitos ocorridos em crianças menores de","alternativas":["1 ano.","2 anos.","5 anos.","6 anos.","10 anos"],"correta":"A"},{"n":30,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"Sobre o indicador de saúde prevalência de uma doença, muito usado em estudos epidemiológicos para descrever a situação de saúde de uma população em determinado momento, assinale a afirmativa correta.","alternativas":["Corresponde ao risco de um indivíduo adoecer ao longo de um período definido.","Corresponde ao número d e casos novos de uma doença em um período determinado.","Corresponde à razão entre os óbitos e os casos confirmados de uma doença em um recorte de tempo.","Corresponde ao número total de casos existentes de uma doença em um determinado período.","Corresponde à proporção de pessoas que evoluem para óbito entre os casos diagnosticados"],"correta":"D"},{"n":31,"disciplina":"Enfermagem","tema":"Gestão em Enfermagem","enunciado":"Uma instituição de saúde decidiu implantar a metodologia Six Sigma em um setor de enfermagem, após identificar falhas recorrentes na administração de medicamentos. Considerando os princípios dessa metodologia para avaliação e melhoria de processos, assinale a afirmativa correta.","alternativas":["A metodologia Six Sigma concentra-se na correção imediata das falhas identificadas, com menor ênfase na mensuração e análise do processo.","A aplicação do Six Sigma prioriza a experiência profissional da equipe, utilizando dados apenas como apoio secundário às decisões do processo.","A implantação do Six Sigma envolve definição do problema, uso de dados para análise das ca usas, aplicação de melhorias e controle sistemático dos resultados obtidos.","O Six Sigma direciona a melhoria dos processos por meio de avaliações pontuais, sem necessidade de monitoramento contínuo.","A implantação do Six Sigma baseia-se na comparaçã o entre profissionais, utilizando resultados individuais como principal referência avaliativa"],"correta":"C"},{"n":32,"disciplina":"Legislação do COFEN","tema":"Lei 7.498/1986","enunciado":"De acordo com a lei que regulamenta o exercício da Enfermagem, assinale a opção que apresenta uma atividade que compete a todos os integrantes da equipe.","alternativas":["Usar dispositivos extraglóticos em situações de iminente risco de morte.","Assumir direção técnica dos serviços de enfermagem e responder legalmente pela instituição de saúde.","Solicitar exames laboratoriais de acordo com o protocolo institucional.","Realizar diagnóstico de Enfermagem e prescrição da assistência.","Participar da elaboração, execução e avaliação dos planos assistenciais de saúde. XI"],"correta":"E"},{"n":33,"disciplina":"Enfermagem","tema":"Saúde da Mulher","enunciado":"Em uma unidade de saúde da atenção básica, uma paciente acompanhada realizou exame citopatológico do colo do útero, cujo resultado apresentou alteração sugestiva de neoplasia. Diante desse resultado, a paciente foi encaminhada para um serviço de maior complexidade para confirmação diagnóstica e tratamento específico. Essa conduta evidencia a aplicação do seguinte princípio organizativo do SUS:","alternativas":["equidade.","integralidade.","regionalização","hierarquização.","descentralização"],"correta":"D"},{"n":34,"disciplina":"Legislação do SUS","tema":"Redes de Atenção à Saúde","enunciado":"Um Consórcio Intermunicipal de Saúde decidiu, por conta própria, criar uma comissão para acompanhar, controlar e avaliar as redes de saúde que estivessem nas regiões de saúde sob sua abrangência. Sobre essa medida, de acordo com as disposições da Lei Orgânica da Saúde acerca das atribuições e competências das três esferas de gestão do SUS, assinale a afirmativa correta.","alternativas":["Está de acordo com a legislação, pois trata -se de uma competência da direção municipal do SUS.","Está em desacordo com a legislação, pois trata -se de uma competência da direção nacional do SUS.","Está de acordo com a legislação, pois trata -se de uma atribuição comum das três esferas de gestão do SUS.","Está em desacordo com a legislação, pois trata -se de uma competência da direção estadual do SUS.","Está de acordo com a legislação, pois trata -se de uma competência da direção municipal e estadual do SUS"],"correta":"D"},{"n":35,"disciplina":"Enfermagem","tema":"Atenção Primária à Saúde","enunciado":"Uma equipe de saúde realizou as seguintes ações em sua área de cobertura: I. O rastreamento de Diabetes Mellitus tipo 2 e Hipertensão Arterial Sistêmica. II. A implantação de grupos comunitários para incentivo à alimentação saudável e prática regular de atividade física. III. O encaminhamento de usuários com sequelas funcionais, após AVC, para acompanhamento multiprofissional e realização de fisioterapia. As ações descritas correspondem, respectivamente, aos seguintes níveis de prevenção:","alternativas":["primária, secundária e terciária.","secundária, primária e terciária.","primária, terciária e secundária.","secundária, primária e quaternária.","terciária, secundária e quaternária"],"correta":"B"},{"n":36,"disciplina":"Legislação do SUS","tema":"Lei 8.080/1990 - Princípios e Diretrizes","enunciado":"Uma usuária de 67 anos, atendida pelo Sistema Único de Saúde (SUS), compareceu a uma Unidade Básica de Saúde para consulta médica. Durante o atendimento, não foi permitida a entrada de sua acompanhante e o médico não prestou informações claras sobre o diagnóstico e o tratamento proposto . Além disso, o médico e o enfermeiro estavam sem crachá ou outra identificação visível. Nesse caso, com base nos direitos dos usuários do SUS, avalie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O usuário do SUS tem direito a receber informações claras, objetivas e compreensíveis sobre se u estado de saúde, o diagnóstico, os riscos, os benefícios e as alternativas de tratamento. ( ) O usuário do SUS tem direito de ser acompanhado por pessoa de sua livre escolha durante consultas, exames e procedimentos. ( ) Não é obrigatório que o crach á ou outras formas de identificação estejam visíveis no momento do atendimento, desde que o profissional se identifique verbalmente. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – F.","F – V – V.","F – F – F"],"correta":"C"},{"n":37,"disciplina":"Legislação do SUS","tema":"Direitos dos Usuários do SUS","enunciado":"Em uma Unidade de Pronto Atendimento (UPA) do SUS, um usuário será submetido a um procedimento diagnóstico invasivo. Antes do procedimento, ele solicitou: I. explicações claras sobre os objetivos e os riscos do procedimento; II. a presença de um acompanhante de sua livre escolha durante o exame; e III. acesso ao conteúdo de seu prontuário, com fornecimento de cópia para levar a outro serviço. Considerando a Carta dos Direitos dos Usuários da Saúde, assinale a opção que indica a conduta correta do serviço de saúde.","alternativas":["Informar apenas após a realização do procedimento, para evitar ansiedade do usuário, e negar acesso ao prontuário por se tratar de documento interno do serviço.","Deve p restar informações gerais, mas dispensar o consentimento do usu ário, uma vez que os procedimentos indicados pela equipe médica não podem ser recusados.","Permitir acesso ao prontuário apenas em caso de encaminhamento formal, sem a obrigação de fornecer cópia ao usuário ou à pessoa por ele autorizada.","Prestar informações sobre os objetivos, os riscos e os benefícios do procedimento, assegurar o consentimento livre do paciente, permitir que um acompanhante esteja presente em consultas e exames e garantir o acesso ao prontuário.","Autorizar um acompanha nte apenas em internação e restringir informações ao mínimo necessário, por se tratar de decisão técnica exclusiva da equipe. XI"],"correta":"D"},{"n":38,"disciplina":"Enfermagem","tema":"Saúde do Trabalhador","enunciado":"A Secretaria Municipal de Saúde pretende implementar um programa de promoção da saúde do trabalhador (ex.: prev enção de hipertensão e diabetes, ergonomia e vacinação). Para dar legitimidade às diretrizes e acompanhar a execução do programa, a equipe precisa observar as instâncias formais de participação da comunidade no SUS, previstas em lei. Assinale a opção que d escreve corretamente essas instâncias e suas características essenciais.","alternativas":["O Conselho de Saúde é uma instância temporária e consultiva, convocada apenas quando há necessidade do gestor; sua composição é livremente definida pela Secretaria de Saúde.","O Conselho de Saúde é um órgão colegiado permanente e deliberativo, com participação paritária de representantes do governo, dos prestadores, dos profissionais de saúde e dos usuários.","A Conferência de Saúde é um órgão colegiado permanente e deliberativo, que se reúne a cada 4 anos, para avaliar a situação de saúde e propor diretrizes; o Conselho de Saúde reúne-se ordinariamente apenas a cada 4 anos, para aprovar o plano de saúde.","A definição e o controle social das políticas do SUS competem exclusivamente às Comissões Intergestores (CIT/CIB), inexistindo participação direta dos usuários em instâncias colegiadas.","A participação social no SUS ocorre por meio de ouvidorias e audiências públicas, que substituem, integralmente, conselhos e conferências como instâncias formais"],"correta":"B"},{"n":39,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"A Secretaria Municipal de Saúde identificou um aumento expressivo de casos suspeitos de dengue em determinados bairros. A coordenação de Vigilância em Saúde solicitou às Unidades Básicas de Saúde (UBS) a reorga nização do processo de trabalho para integrar busca ativa e notificação de casos; orientar a população sobre eliminação de criadouros; e articular ações intersetoriais no território. O gestor de uma UBS, entretanto, afirmou que “vigilância é atribuição exc lusiva do setor de Vigilância” e que a Atenção Básica deve limitar -se ao atendimento clínico individual por demanda espontânea, sem organização por território ou população adscrita. À luz da Política Nacional de Atenção Básica (PNAB), assinale a opção que apresenta a orientação correta.","alternativas":["Integrar a Vigilância em Saúde e a Atenção Básica, organizando ações no território e sobre a população adscrita, reconhecendo a Atenção Básica como principal porta de entrada e centro de comunicação da Rede de Atençã o à Saúde (RAS).","Manter a separação entre setores: a notificação e a busca ativa devem ser executadas somente pela Vigilância em Saúde, cabendo à Atenção Básica apenas tratar clinicamente os casos que comparecerem à UBS.","Substituir a lógica territo rial por equipes móveis sem adscrição, atuando apenas conforme demanda do dia, pois territorialização e população adscrita são diretrizes facultativas.","Aguardar diretriz estadual/federal específica para iniciar articulação intersetorial, pois a PNAB nã o vincula Atenção Básica a processos de trabalho baseados em determinantes, riscos e danos.","Concentrar o enfrentamento exclusivamente em serviços de urgência e hospitais, suspendendo o papel da Atenção Básica como coordenadora do cuidado e ordenadora d a rede durante o surto. XI"],"correta":"A"},{"n":40,"disciplina":"Legislação do SUS","tema":"Financiamento do SUS e LC 141/2012","enunciado":"A Secretaria Municipal de Saúde está finalizando a proposta da Lei de Diretrizes Orçamentárias (LDO) do próximo exercício e precisa consolidar as metas e a alocação de recursos da área da saúde. Durante a reunião, um assessor sugeriu que a Programação Anual de Saúde (PAS) fosse enviada ao Conselho de Saúde apenas depois do encaminhamento da LDO ao Legislativo e que o Relatório Anual de Gestão (RAG) fosse enviado somente aos órgãos de controle externo, sem apreciaçã o do Conselho, por entender que o Conselho teria função meramente consultiva. À luz das normas do SUS sobre planejamento e controle social, assinale a opção que apresenta a conduta correta.","alternativas":["Encaminhar a PAS ao Poder Legislativo juntamente com a LOA, su bmetendo-a ao Conselho após a aprovação orçamentária; e enviar o RAG até 30 de junho do ano seguinte, sem necessidade de parecer do Conselho.","Elaborar o Plano de Saúde com vigência anual (ano - calendário) e utilizar a PAS como instrumento quadrienal, por serem ambos documentos internos da Secretaria, sem necessidade de submissão ao Conselho.","Elaborar a PAS e encaminhá -la à aprovação do respectivo Conselho de Saúde antes da data de encaminhamento da LDO; e elaborar o RAG anualmente, envi ando-o ao Conselho de Saúde até 30 de março do ano seguinte, para emissão de parecer conclusivo.","Encaminhar previamente o Plano de Saúde ao Ministério da Saúde para homologação e, somente depois, submetê -lo ao Conselho; e dispensar a PAS quando houver pactuação interfederativa por Contrato Organizativo de Ação Pública em Saúde (COAP).","Substituir a PAS pelo Relatório Detalhado do Quadrimestre Anterior (RDQA), que é o instrumento anual de planejamento e deve ser aprovado pelo Conselho antes do envio da LDO"],"correta":"C"},{"n":41,"disciplina":"Enfermagem","tema":"Diabetes Mellitus","enunciado":"Durante o atendimento a um paciente do sexo masculino com diabetes mellitus tipo 1, em uso regular de insulina NPH e insulina regular, o paciente informou que passou a utili zar ácido acetilsalicílico (AAS), em dose diária, para prevenção de acidente vascular cerebral, conforme orientação recebida em outro serviço. Considerando os princípios da administração segura de medicamentos e as interações medicamentosas associadas ao uso concomitante de AAS e insulina, assinale a afirmativa correta.","alternativas":["O uso de AAS não interfere na ação da insulina, não sendo necessária qualquer orientação adicional ao paciente.","O AAS pode potencializar o efeito hipoglicemiante da insulina, aumentando o risco de hipoglicemia.","A insulina neutraliza o efeito anticoagulante do AAS, tornando o medicamento totalmente ineficaz.","A principal interação entre AAS e insulina é a redução da biodisponibilidade da insulina, elevando os níveis glicêmicos.","A ingestão de carboidratos de forma contínua é suficiente para neutralizar a interação dos medicamentos"],"correta":"B"},{"n":42,"disciplina":"Enfermagem","tema":"Fundamentos e Semiotécnica","enunciado":"Durante a assistência a um paciente com desconforto respiratório, foi necessário realizar punção arterial para coleta de sangue para gasometria. Considerando os princípios técnicos e de segurança desse procedimento, é correto afirmar que","alternativas":["a punção arterial deve ser realizada preferencialmente na artéria cubital, após avaliação da circulação colateral.","se o paciente apresentar pulso arterial facilmente palpável, a prova de Allen é dispensável.","a coleta de gasometria arterial pode ser realizada com seringa comum, dispensando cuidados com presença de ar.","tentativas de punção sem sucesso que durem mais de 30 segundos podem ocasionar alterações na PaO2.","a reutilização de uma mesma artéria para coleta de sangue frequentes é contraindicada em qualquer caso"],"correta":"D"},{"n":43,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"Um paciente acamado apresentou Lesão por Pressão (LPP) na região escapular, que evoluiu com a perda total da espessura da pele e com tecido adiposo subcutâneo visível. De acordo com as características descritas, esse paciente apresenta","alternativas":["LPP estágio 1.","LPP estágio 2.","LPP estágio 3.","LPP estágio 4.","LPP tissular profunda"],"correta":"C"},{"n":44,"disciplina":"Enfermagem","tema":"Diabetes Mellitus","enunciado":"De acordo com os parâmetros da Sociedade Brasileira de Diabetes, os valores de glicemia em jejum considerados normais para um paciente adulto estão entre","alternativas":["70 e 99 mg/dL.","80 e 100 mg/dL.","90 e 110 mg/dL.","99 e 115 mg/dL.","110 e 125 mg/dL"],"correta":"A"},{"n":45,"disciplina":"Enfermagem","tema":"Urgência e Emergência","enunciado":"Durante o atendimento a um paciente adulto, vítima de acidente com traumatismo na cabeça e pescoço, foi necessário realizar a abertura e permeabilidade das vias aéreas. Considerando os princípios do manejo inicial das vias aéreas nesse tipo de trauma, assinale a afirmativa correta.","alternativas":["A abertura das vias aéreas de um paciente adulto com risco de lesão cervical deve ser realizada com a manobra de inclinação da cabeça e a elevação do queixo.","A manobra de anteriorização da mandíbula ( jaw thrust ) é a mais indicada para a abertura das vias aéreas em pacientes com esse tipo de trauma.","A manutenção da via aérea pode ser realizada inicialmente com dispositivos supraglóticos, desde que nã o haja rebaixamento do nível de consciência.","A abertura das vias aéreas deve ser realizada apenas após a estabilização definitiva da coluna cervical e a conclusão da avaliação secundária.","O uso de cânula orofaríngea é indicada sempre que houver traumatismo na região da cabeça e pescoço, independentemente do nível de consciência do paciente. XI"],"correta":"B"},{"n":46,"disciplina":"Enfermagem","tema":"Saúde da Criança e do Adolescente","enunciado":"Com base nos componentes da Ressuscitação Cardiopulmonar (RCP) de alta qualidade para bebês e crianças em parada cardiorrespiratória (PCR), av alie as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) Para bebês e crianças, recomenda -se minimizar as interrupções durante a RCP, mantendo as pausas nas compressões torácicas inferiores a 10 segundos. ( ) Na compressão torácica em bebês, recomenda -se comprimir o esterno usando a técnica dos dois polegares, com as mãos circundando o tórax ou a base de uma das mãos. ( ) A tradicional técnica de 2 dedos para RCP em bebês menores de 1 ano não é mais recomendada, visto que não alcança a profundidade ideal de compressão. As afirmativas são, respectivamente,","alternativas":["V – F – V.","F – V – F.","V – V – V.","F – F – F.","V – V – F"],"correta":"C"},{"n":47,"disciplina":"Enfermagem","tema":"Hipertensão Arterial","enunciado":"Um paciente adulto, 45 anos, procurou a unidade de pronto atendimento apresentado sinais e sintomas característicos de crise hipertensiva. Essa condição é caracterizada por uma elevação aguda e importante da pressão arterial, com valores que abrangem","alternativas":["PAD ≥ 90 mmHg.","PAS ≥ 150 mmHg.","PAD ≥ 100 mmHg.","PAS ≥ 160 mmHg.","PAS ≥ 180 mmHg"],"correta":"E"},{"n":48,"disciplina":"Enfermagem","tema":"Saúde do Trabalhador","enunciado":"Uma trabalhadora de 34 anos, auxiliar administrativa, procura o serviço de saúde ocupacional relatando dor no punho direito, com irradiação para o polegar, que piora ao digitar e ao realizar movimentos repetitivos de pinça. Ao exame físico, apresenta dor à palpação na região do processo estiloide do rádio e teste de Finkelstein positivo. Sobre o quadro clínico descrito e os riscos ocupacionais envolvidos, assinale a afirmativa correta.","alternativas":["O quadro é compatível com Tendinite de De Quervain, agravo relacionado a movimentos repetitivos e esforço contínuo do punho e polegar.","Os sinais e sintomas são característicos de Síndrome do Túnel do Carpo , decorrente principalmente da compressão do nervo mediano.","O quadro clínico sugere epicondilite lateral, caracterizada por dor na base do polegar, geralmente associada a processo degenerativo articular.","O quadro sugere artrite reumatoide, doença inflamatória sistêmica de origem autoimune, que pode ter sid o agravada pelas atividades laborais.","Os sinais descritos indicam tenossinovite dos extensores do punho de origem inflamatória sistêmica, sem relação direta com a atividade laboral desempenhada"],"correta":"A"},{"n":50,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"A infecção pelo SARS -CoV-2 pode variar de casos sem sintomas a casos com manifestações leves, moderados, graves e críticos. Os sinais e sintomas mais comuns incluem febre ou ca lafrios, tosse, fadiga, anorexia, dispneia, mialgia e dor de cabeça. No entanto, outros sintomas não específicos, como dor de garganta, congestão nasal ou coriza, e dor de cabeça, também foram reportados por casos confirmados de Covid-19. Assinale a opção que apresenta a principal forma de evitar os casos graves dessa doença e as possíveis sequelas.","alternativas":["Uso de máscaras.","Vacinação.","Distanciamento físico.","Higienização das mãos.","Limpeza e desinfecção de superfícies com água e sabão e detergente"],"correta":"B"},{"n":51,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"A notificação compulsória é um mecanismo essencial de vigilância em Saúde Pública, que exige que médicos, profissionais de saúde e responsáveis por estabelecimentos de saúde comuniquem a ocorrência de suspeitas ou confirmações de doenças, agravos ou eventos de saúde pública às autoridades de saúde. Assinale a opção que apresenta uma condição de notificação compulsória semanal.","alternativas":["Eventos adversos graves ou óbitos pós-vacinação.","Síndrome da Rubéola Congênita.","Acidente por animal peçonhento.","Leptospirose.","Doença aguda pelo vírus Zika. XI"],"correta":"E"},{"n":52,"disciplina":"Enfermagem","tema":"Saúde do Trabalhador","enunciado":"Vigilância em Saúde do Trabalhador, um dos componentes do Sistema Nacional de Vigilância em Saúde, compreende o conjunto de ações que visam à promoção da saúde, à prevenção da morbimortalidade e à redução de riscos e vulnerabilidades na população trabalhadora, por meio da integração de ações que intervenham nas doenças e agravos e seus determinantes decorrentes dos modelos de desenvolvimento, de processo s produtivos e de trabalho. Sobre os objetivos da Política Nacional de Saúde do Trabalhador e da Trabalhadora, avalie as afirmativas a seguir. I. A incorporação da categoria trabalho como determinante do processo saúde -doença na coletividade (não individualmente). II. A identificação da situação do trabalho dos usuários nas ações e nos serviços de saúde do SUS com as suas possíveis consequências para a saúde. III. A garantia da universalidade na atenção à saúde do trabalhador, que pressupõe a inserção de ações de saúde do trabalhador em todas as instâncias e pontos da Rede de Atenção à Saúde do SUS. Está correto o que se afirma em","alternativas":["II, apenas.","I e II, apenas.","I e III, apenas.","II e III, apenas.","I, II e III"],"correta":"A"},{"n":53,"disciplina":"Enfermagem","tema":"Epidemiologia e Vigilância em Saúde","enunciado":"As doenças crônicas não transmissíveis (DCNT) atingem, especialmente, as populações mais vulneráveis, como as de baixa renda e baixa escolaridade, devido à maior exposição aos fatores de risco ou ao acesso restrito às informações e aos serviços de saúde. As DCNT são responsáveis pela maior carga de morbimortalidade no mundo, acarretando perda de qualidade de vida, limitações, incapacidades, além de alta taxa de mortalidade prematura. Assinale a opção que determina a doença (ou grupo de doenças) que representa a principal causa de óbito em indivíduos acima dos 50 anos no Brasil.","alternativas":["Diabetes.","Neoplasias.","Doença renal crônica.","Doenças cardiovasculares.","Doenças pulmonares crônicas"],"correta":"D"},{"n":54,"disciplina":"Enfermagem","tema":"Saúde do Adulto","enunciado":"As ações estratégicas para a promoção da saúde e para o enfrentamento dos fatores de risco das doenças e dos agravos não transmissíveis, são organizadas a partir da vinculação dos fatores de risco para doenças e agravos não transmissíveis (Dant). São ações correlatas às especificidades de cada tema, e objetivam indicar foco e direção para alcançar as metas do Plano de Dant. Assinale a opção que representa uma ação do Eixo Prevenção de Doenças e Agravos à Saúde.","alternativas":["Implementar estratégias de formação dos profissionais de saúde da APS para a detecção prec oce de fatores de risco para as DCNT e a obesidade, bem como desenho de iniciativas para a redução individual e coletiva dos mesmos no território, envolvendo os ciclos de vida.","Desenvolver e ofertar aos Estados, ao Distrito Federal e aos Municípios, a s tecnologias para a interoperabilidade de dados dos sistemas de informação em saúde para qualificar a vigilância de lesões por causas externas.","Elaborar e disponibilizar para a rede de ensino da educação básica, itinerários formativos sobre prevenção das DCNT e dos agravos, da promoção da saúde e do desenvolvimento sustentável.","Ampliar estratégias de promoção do envelhecimento saudável ao longo de toda a vida, com a inclusão de linhas de cuidado e de adaptação de processos terapêuticos às especificidades da pessoa idosa.","Realizar regularmente a Pesquisa Nacional de Saúde do Escolar (PeNSE). XI"],"correta":"A"},{"n":55,"disciplina":"Enfermagem","tema":"Saúde do Trabalhador","enunciado":"O Grupo de Medicina do Trabalho tem como objetivo manter o bem-estar físico, mental e social dos servidores nas suas ocupações e atuar na prevenção de doenças que possam se originar no ambiente de trabalho. Sobre o Grupo de Medicina do Trabalho, assinale a afirmativa correta.","alternativas":["O Grupo de Medicina do Trabalho será formado por, no mínimo, 5 (cinco) médicos peritos, com especialização em medicina do trabalho e 3 (três) engenheiros de segurança do trabalho e coordenado por um perito médico, designado pelo Diretor-Presidente do TJ -MS, por indicação do titu lar da Diretoria de Perícia Médica.","Não é função do Grupo de Medicina do Trabalho emitir pareceres e laudos técnicos mediante a solicitação da COPEM.","É função do Grupo de Medicina do Trabalho coordenar, controlar, acompanhar e supervisionar a execu ção das atividades de perícia médica previdenciária e em saúde realizadas por órgãos, unidades e demais agentes da Perícia Médica.","É função do Grupo de Medicina do Trabalho monitorar a emissão de laudos médicos sobre concessão de benefícios previdenciários, realização de inspeções em locais de trabalho, avaliação de nexo causal de acidentes do trabalho e doença profissional ou do trabalho e da avaliação pericial nos exames admissionais.","O Grupo de Medicina do Trabalho será composto por peritos, servidores estaduais ou profissionais credenciados pela AGEPREV, designados por prazo determinado ou por convocação eventual, para realizar levantamentos e participar da avaliação de ambientes de trabalho"],"correta":"E"}]}] as const;
export async function sincronizarFGVAleamTjms2026(){
 const usuario=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!usuario)return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const banco=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const vistos=new Set(banco.map(q=>norm(q.enunciado)));
 const disciplinas=new Map<string,number>();let inseridas=0,existentes=0,repetidas=0;
 for(const lote of LOTES)for(const q of lote.itens){
  if(!q.enunciado.trim()||q.alternativas.length!==5||q.alternativas.some(a=>!a.trim())||
     !["A","B","C","D","E"].includes(q.correta)||
     new Set(q.alternativas.map(a=>a.toLowerCase().trim())).size!==5)
    throw new Error("[aleam-tjms] Questão inválida "+lote.codigo+"/"+q.n);
  const origemId="fgv-"+lote.codigo+"-tipo1-q"+String(q.n).padStart(2,"0");
  if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
  const hash=norm(q.enunciado);if(vistos.has(hash)){repetidas++;continue;}
  let disciplinaId=disciplinas.get(q.disciplina);
  if(!disciplinaId){
   let d=await prisma.disciplina.findFirst({where:{usuarioId:usuario.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
   if(!d)d=await prisma.disciplina.create({data:{usuarioId:usuario.id,nome:q.disciplina},select:{id:true}});
   disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
  }
  await prisma.questao.create({data:{
   usuarioId:usuario.id,disciplinaId,tema:q.tema,fonte:FONTE_PROVAS_REAIS,origemId,
   dificuldade:"medio",banca:"FGV",ano:lote.ano,orgao:lote.orgao,cargo:lote.cargo,fonteUrl:lote.prova,
   enunciado:q.enunciado,
   explicacao:"FGV, "+lote.orgao+", "+lote.ano+", "+lote.cargo+", questão "+q.n+
     ". Gabarito definitivo: alternativa "+q.correta+". Prova: "+lote.prova+" | Gabarito: "+lote.gabarito,
   alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
  }});
  inseridas++;vistos.add(hash);
 }
 console.log("[aleam-tjms-2026] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" duplicadas ignoradas.");
 return {inseridas,existentes,repetidas};
}
